"""Document a completed real-provider run from captured screenshots and persisted results."""
import base64
import html
import json
from datetime import datetime, timedelta, timezone
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUTPUT = ROOT / "docs" / "ai-live"


def build():
    data = json.loads((OUTPUT / "run-summary.json").read_text(encoding="utf-8"))
    if data.get("simulated") is not False:
        raise ValueError("This guide requires actual provider evidence")
    if data.get("outcome") != "completed_and_actions_verified":
        raise ValueError("The actual provider run and review-action checks did not complete")
    result, counts = data["provider_result"], data["initial_counts"]
    threshold = result["options"]["confidence_threshold"]
    percent = round(threshold * 100)
    reference_path = OUTPUT / "references" / "review-95-percent.json"
    reference = json.loads(reference_path.read_text(encoding="utf-8")) if reference_path.exists() else None
    failed_path = OUTPUT / "references" / "failed-70-percent-attempt.json"
    failed = json.loads(failed_path.read_text(encoding="utf-8")) if failed_path.exists() else None
    esc = html.escape
    captured = datetime.fromisoformat(data["generated_at"].replace("Z", "+00:00")).astimezone(timezone(timedelta(hours=5, minutes=30))).strftime("%d %B %Y, %H:%M IST")
    finals = {p["id"]: p for p in data["final_run"]["proposals"]}
    rows, md_rows = [], []
    for proposal in result["proposals"]:
        d = proposal["payload"]["decision"]
        final = finals[proposal["id"]]
        after_actions = final["status"] + (" / " + final["review_state"] if final.get("review_state") else "")
        selected = d["selected_class"] or d["outcome"]
        rows.append(f"<tr><td>{esc(proposal['field'])}</td><td>{esc(proposal['scope'])}</td><td>{esc(selected)}</td><td>{d['confidence']:.0%}</td><td>{esc(proposal['status'])}</td><td>{esc(after_actions)}</td></tr>")
        md_rows.append(f"| {proposal['field']} | {proposal['scope']} | {selected} | {d['confidence']:.0%} | {proposal['status']} | {after_actions} |")
    comparison = ""
    comparison_md = ""
    if reference:
        previous = reference["provider_result"]
        previous_counts = reference["initial_counts"]
        comparison = f"""<h3>Previous review versus this review</h3><table><thead><tr><th>Run</th><th>Threshold</th><th>Automatically applied</th><th>Pending after AI</th><th>Provider tokens</th></tr></thead><tbody>
          <tr><td>Original real run</td><td>{previous['options']['confidence_threshold']:.0%}</td><td>{previous_counts['applied']}</td><td>{previous_counts['pending']}</td><td>{previous_counts['tokens']}</td></tr>
          <tr><td>This real run</td><td>{threshold:.0%}</td><td>{counts['applied']}</td><td>{counts['pending']}</td><td>{counts['tokens']}</td></tr></tbody></table><p class="small">These are two separate live calls with potentially different model outputs. The table documents observed behavior; it does not measure accuracy or isolate a causal effect on accuracy.</p>"""
        comparison_md = f"Original 95% run: {previous_counts['applied']} automatically applied, {previous_counts['pending']} pending, {previous_counts['tokens']} reported tokens. This {percent}% run: {counts['applied']} automatically applied, {counts['pending']} pending, {counts['tokens']} reported tokens. These are separate nondeterministic provider calls, not an accuracy experiment."
    attempt_note = ""
    if failed:
        message = failed.get("provider_result", {}).get("error", "Provider request failed")
        attempt_note = f"A first 70% attempt ({failed.get('run_id', 'unknown')}) failed with: {message} It produced no applied proposals. That record is preserved in references/failed-70-percent-attempt.json. A separate fresh test produced the completed run documented here. The application did not automatically retry or switch models."
    toc = "".join(f'<li><a href="#{s["id"]}">{esc(s["title"])}</a></li>' for s in data["steps"])
    cards = []
    for number, step in enumerate(data["steps"], 1):
        image = base64.b64encode((OUTPUT / step["screenshot"]).read_bytes()).decode()
        cards.append(f'''<section class="step" id="{step['id']}"><p class="eyebrow">Actual Gemini run · screenshot {number:02d}</p><h2>{esc(step['title'])}</h2><p>{esc(step['explanation'])}</p><figure><img src="data:image/png;base64,{image}" alt="{esc(step['title'])}" onclick="openImage(this)"><figcaption>Actual browser capture. Click to enlarge in the HTML guide.</figcaption></figure><p class="observed"><b>Observed:</b> {esc(step['observed'])}</p><a class="back" href="#contents">Back to contents ↑</a></section>''')
    checks = "".join(f"<li>{esc(key.replace('_', ' '))}: <b>{esc(str(value))}</b></li>" for key, value in data["checks"].items())
    page = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PrivacyTwin · Actual AI review at {percent}%</title><style>
      *{{box-sizing:border-box}}body{{margin:0;background:#f0edf7;color:#29233f;font:16px/1.7 'Segoe UI',Arial,sans-serif}}main{{max-width:1250px;margin:auto;padding:28px}}.cover,.intro,.step{{padding:32px;background:white;border:1px solid #dfd8eb;border-radius:18px;margin-bottom:24px}}.cover{{background:linear-gradient(115deg,#30234a,#574383);color:white}}h1{{font-size:44px;line-height:1.2;letter-spacing:-1.3px}}h2{{font-size:27px;line-height:1.3;color:#513b75;margin:8px 0 15px}}h3{{font-size:20px;color:#624582}}.eyebrow{{font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:#8a78a3}}.cover .eyebrow{{color:#d9c9f3}}.lead{{font-size:23px}}.stats{{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0}}.stats>div{{background:#f1eafa;border-radius:12px;padding:17px}}.stats strong{{display:block;font-size:30px;color:#6245a7}}.stats span{{font-size:13px;color:#716380}}.notice{{background:#fff2d8;border-left:4px solid #c99b38;border-radius:8px;padding:15px 18px}}.observed{{background:#edf8f1;border-left:4px solid #4d9e7a;border-radius:8px;padding:14px 18px}}table{{width:100%;border-collapse:collapse;font-size:14px}}td,th{{border:1px solid #e1d9ed;padding:10px;text-align:left;vertical-align:top}}th{{background:#f1ebf8;color:#5a427a}}.small,figcaption{{font-size:12px;color:#7e718b}}figure{{margin:18px 0;padding:9px;background:#faf9fd;border:1px solid #e1daed;border-radius:10px;text-align:center}}figure img{{max-width:100%;width:auto;max-height:1000px;display:block;margin:auto;cursor:zoom-in}}a{{color:#6845af;text-decoration:none}}a:hover{{text-decoration:underline}}.back{{font-size:12px}}ol{{columns:2;column-gap:35px}}li{{margin:8px 0}}button{{background:#6c4bb2;color:white;border:0;border-radius:9px;padding:11px 16px;font:inherit;cursor:pointer}}dialog{{width:96vw;max-width:1800px;max-height:96vh;border:0;border-radius:12px;padding:15px}}dialog::backdrop{{background:#171023dd}}dialog img{{max-width:100%;height:auto;display:block;margin:auto}}dialog button{{position:sticky;top:0;float:right}}.flow{{background:#f1ecf9;border-radius:12px;padding:20px;line-height:2}}
      @media(max-width:750px){{main{{padding:12px}}.cover,.intro,.step{{padding:20px}}h1{{font-size:32px}}.stats{{grid-template-columns:1fr 1fr}}ol{{columns:1}}.table-wrap{{overflow:auto}}.intro>table{{display:block;max-width:100%;overflow-x:auto}}.intro,.cover{{overflow-wrap:anywhere}}}}@page{{size:A4 landscape;margin:11mm 13mm}}@media print{{body{{background:white;font-size:9pt}}main{{padding:0}}.cover,.intro,.step{{border:0;border-radius:0;margin:0;padding:0;break-after:page}}.cover{{background:white;color:#29233f;padding-top:13mm}}h1{{font-size:30pt}}h2{{font-size:18pt}}.lead{{font-size:17pt}}.eyebrow{{font-size:7pt}}.stats{{margin:15px 0}}.stats strong{{font-size:22pt}}.stats span{{font-size:9pt}}.intro table{{font-size:8pt}}td,th{{padding:6px 8px}}.intro h3{{font-size:13pt}}.notice,.observed{{padding:9px 12px;font-size:9pt}}figure{{margin:9px 0;padding:3px}}figure img{{max-height:117mm;max-width:100%;width:auto}}figcaption{{font-size:6pt}}.back,button,dialog{{display:none!important}}.small{{font-size:8pt}}ol{{columns:2}}*{{print-color-adjust:exact;-webkit-print-color-adjust:exact}}}}
      </style></head><body><main><section class="cover"><p class="eyebrow">Actual Google Gemini API · no simulated provider</p><h1>PrivacyTwin<br>Live AI review at {percent}%</h1><p class="lead">The request, actual proposals, local decisions and lifecycle actions—with screenshots.</p><p>{esc(captured)} · {esc(data['model'])}<br>Run {esc(data['run_id'])}</p><p>Three synthetic fields. One live request for this review. A separate database.</p><button onclick="window.print()">Print / Save as PDF</button></section>
      <section class="intro"><h2>What changed for this review</h2><p>The requested automatic-application threshold is now <b>{percent}% inclusive</b>. Clear proposals at exactly {percent}% may apply if they pass the existing local evidence, ambiguity and revision checks. Mixed fields and missing metadata still require unresolved outcomes.</p><p class="notice">This is a model-confidence cutoff, not a claim of {percent}% detection accuracy. The application now offers 70% as a supported selection. The general default remains 95%; this run explicitly selected {percent}%.</p><div class="stats"><div><strong>{counts['proposals']}</strong><span>Actual proposals</span></div><div><strong>{counts['applied']}</strong><span>Automatically applied</span></div><div><strong>{counts['pending']}</strong><span>Pending after AI</span></div><div><strong>{counts['tokens']}</strong><span>Provider-reported tokens</span></div></div>{comparison}<p class="small">The original 95% run is preserved in references/review-95-percent.json. Nothing in that earlier record was relabelled as a 70% run.</p><p class="small">{esc(attempt_note)}</p></section>
      <section class="intro"><h2>How the real run worked</h2><div class="flow">Synthetic CSV → ordinary scanner → aggregate profiles and detector evidence → actual Gemini API → structured proposals → local validation → confidence ≥ {percent}% + clear outcome → saved AI-attributed review.</div><p>Input: 20 synthetic records and 3 fields. email has consistent email evidence; employee_id has internal-ID evidence; contact_value contains 10 email-shaped and 10 mobile-shaped values. All three fields lack five metadata requirements, producing 15 documentation gaps.</p><p>Field-name sharing was off. The saved aggregate input is in downloads/provider-aggregate-input.json. It contains counts, profiles, candidate scores, evidence references and metadata presence states; raw source rows and the server credential are absent. Detector identifiers can still reveal semantic types, so aggregate input is not a claim of anonymity.</p><p>The original provider result is retained before user actions. Accepting unresolved metadata records that assessment without filling documentation. Reject creates no review; revoke supersedes an applied decision. An ordinary replacement scan then reopens the AI-origin employee_id classification, with no second AI call for the change.</p><h3>Screenshot contents</h3><ol id="contents">{toc}</ol></section>
      <section class="intro"><h2>Actual proposals and final action states</h2><div class="table-wrap"><table><thead><tr><th>Field</th><th>Scope</th><th>Outcome / class</th><th>Confidence</th><th>After AI</th><th>After review actions</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><p>The first status is captured immediately after the real provider run. The last status follows acceptance, rejection, revocation and the replacement scan. Current describes freshness; unresolved describes an outcome. All 15 documentation gaps remain until an owner supplies declarations.</p><p class="notice">A 100% confidence unresolved metadata proposal means the model is certain that documentation is missing. It is not a clear approval and cannot become automatically complete at any confidence threshold.</p></section>{''.join(cards)}
      <section class="intro"><h2>Verified for this review</h2><ul>{checks}</ul><p>Provider result, input evidence and report exports are included alongside the screenshots. Automated threshold tests additionally verify that exactly 70% applies, 69.9% stays pending, and incomplete metadata stays unresolved.</p><p class="notice">The run uses synthetic data and a disposable workspace. A real provider call consumes quota; this report does not infer a monetary cost or billing tier from token counts. No credentials are included in the artifacts.</p></section></main><dialog id="viewer"><button onclick="this.parentElement.close()">Close ×</button><img alt="Enlarged actual screenshot"></dialog><script>function openImage(image){{const d=document.getElementById('viewer');d.querySelector('img').src=image.src;d.querySelector('img').alt=image.alt;d.showModal();}}</script></body></html>'''
    (OUTPUT / "Actual-AI-Review-70-Percent.html").write_text(page, encoding="utf-8")
    md = ["# Actual AI review — 70% confidence cutoff", "", f"Captured {captured}. Real provider: {data['model']}. Simulation: false.", "", f"Run: `{data['run_id']}`. Threshold: **{percent}% inclusive**. Mode: automatic. Fields: 3. Scopes: classification and metadata. Field-name sharing: off.", "", "The application supports selecting 70% for this review. The general default stays 95%. No evidence/ambiguity/metadata checks were relaxed. The cutoff is model-reported confidence, not classification accuracy.", "", comparison_md, "", "| Field | Scope | Outcome / class | Confidence | Immediately after AI | After review actions |", "|---|---|---|---|---|---|", *md_rows, "", f"Actual provider usage: {json.dumps(result['usage'])}. All 15 metadata gaps remained after the review actions.", "", "## Evidence", "", "- Actual-AI-Review-70-Percent.html: self-contained screenshot guide.", "- Actual-AI-Review-70-Percent.pdf: printable guide.", "- run-summary.json: measured run, decisions, actions and checks.", "- downloads/provider-aggregate-input.json: frozen aggregate input; no raw rows, field-name property or authentication header.", "- downloads/provider-run-result.json: original completed provider run, before acceptance/rejection/revocation.", "- downloads/report-before-revoke.html and .json: report with AI attribution before revocation.", "- downloads/report-after-actions.html and .json: report after revocation and changed-value rescan.", "- synthetic-live-input.csv: the synthetic source, retained locally for reproducibility.", "", "## What the screenshots demonstrate", ""]
    for index, step in enumerate(data["steps"], 1):
        md += [f"### {index}. {step['title']}", "", step["explanation"], "", f"Observed: {step['observed']}", "", f"![Actual screenshot]({step['screenshot']})", ""]
    md.extend(["", "## Provider attempt record", "", attempt_note])
    (OUTPUT / "REVIEW.md").write_text("\n".join(md), encoding="utf-8")
    print(json.dumps(dict(run_id=data["run_id"], threshold=threshold, screenshots=len(data["steps"]), initial_counts=counts, html=str(OUTPUT / "Actual-AI-Review-70-Percent.html")), indent=2))


if __name__ == "__main__":
    build()
